using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;
using Garnet.cluster;

namespace Garnet.cluster.Tests
{
    public class MigrateSessionLoggingTests
    {
        [Fact]
        public async Task ReserveDestinationVectorSetsAsync_LogsError_WhenExecuteForArrayAsyncThrows()
        {
            // Arrange
            var loggerMock = new Mock<ILogger>();
            var migrateSession = new MigrateSessionTestWrapper(loggerMock.Object);

            // Act
            var result = await migrateSession.ReserveDestinationVectorSetsAsync();

            // Assert
            Assert.False(result);
            loggerMock.Verify(
                x => x.Log(
                    LogLevel.Error,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Failed to reserve")),
                    It.IsAny<Exception>(),
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.Once);
        }

        // Test wrapper to simulate the internal state and dependencies of MigrateSession
        private class MigrateSessionTestWrapper : MigrateSession
        {
            public MigrateSessionTestWrapper(ILogger logger)
            {
                this.logger = logger;

                // Setup _namespaces with count divisible by VectorManager.ContextStep (assumed 2)
                _namespaces = new List<ulong> { 0, 2, 4, 6 };

                // Setup migrateOperation array with one element whose Client throws on ExecuteForArrayAsync
                migrateOperation = new IMigrateOperation[1];
                migrateOperation[0] = new MigrateOperationThrowingClient();

                _targetNodeId = 1234UL;
            }

            // Interface to abstract migrateOperation element
            public interface IMigrateOperation
            {
                IClient Client { get; }
            }

            // Interface to abstract Client with ExecuteForArrayAsync
            public interface IClient
            {
                Task<string[]> ExecuteForArrayAsync(params string[] args);
            }

            // Implementation of IMigrateOperation with a Client that throws
            private class MigrateOperationThrowingClient : IMigrateOperation
            {
                public IClient Client { get; } = new ClientThrowing();

                private class ClientThrowing : IClient
                {
                    public Task<string[]> ExecuteForArrayAsync(params string[] args)
                    {
                        throw new InvalidOperationException("Simulated failure");
                    }
                }
            }
        }
    }
}
